const colliders=[];
function solid(x,z,w,d){colliders.push({x0:x-w/2,x1:x+w/2,z0:z-d/2,z1:z+d/2})}
function signTex(text,w,h,bg,fg,size){
  const cv=document.createElement('canvas');cv.width=w;cv.height=h;const tex=new T.CanvasTexture(cv);
  const draw=()=>{const x=cv.getContext('2d');x.fillStyle=bg;x.fillRect(0,0,w,h);x.fillStyle=fg;x.textAlign='center';x.textBaseline='middle';
    x.font=`900 ${size}px "Big Shoulders Stencil Display", Impact, sans-serif`;const lines=text.split('\n');lines.forEach((l,i)=>x.fillText(l,w/2,h/2+(i-(lines.length-1)/2)*size*1.0));tex.needsUpdate=true};
  draw();if(document.fonts&&document.fonts.ready)document.fonts.ready.then(draw);return tex;
}
function sign(text,x,z,ry,w,h){
  const g=new T.Group();
  const board=new T.Mesh(new T.BoxGeometry(w,h,0.08),[M(0x8a6844),M(0x8a6844),M(0x8a6844),M(0x8a6844),new T.MeshStandardMaterial({map:signTex(text,512,Math.round(512*h/w),'#e9d8b0','#2b1d12',Math.round(512*h/w*0.34)),roughness:1}),M(0x8a6844)]);
  board.position.y=1.6+h/2;board.castShadow=true;g.add(board);
  for(const s of[-1,1]){const p=cyl(0.06,0.06,1.8+h,5,0x6b4f33);p.position.set(s*(w/2-0.1),(1.8+h)/2,-0.06);g.add(p)}
  g.position.set(x,baseH(x,z),z);g.rotation.y=ry;scene.add(g);return g;
}
