  addG(0.35,0.34,EAST_GATE_Z1-EAST_GATE_Z0,steel,FENCE_X1,baseH(FENCE_X1,39)+4.0,39);
  // The fence's collision spans stop at the last whole 2.5 m / 2.4 m panel, short of each gate post; close those
